import React, { useEffect, useRef, useState } from 'react';
import { View, Image, StyleSheet, Animated, Easing, Text } from 'react-native';
import { onAuthStateChanged } from 'firebase/auth';
import { auth } from '../services/firebaseConfig';
import { LinearGradient } from 'expo-linear-gradient';

export default function SplashLogoScreen({ navigation }: any) {
  const logoOpacity = useRef(new Animated.Value(0)).current;
  const logoScale = useRef(new Animated.Value(0.92)).current;
  const progress = useRef(new Animated.Value(0)).current;
  const pulse = useRef(new Animated.Value(1)).current;
  const glow = useRef(new Animated.Value(0)).current;
  const [percentage, setPercentage] = useState(0);

  useEffect(() => {
    Animated.parallel([
      Animated.timing(logoOpacity, {
        toValue: 1,
        duration: 700,
        easing: Easing.out(Easing.cubic),
        useNativeDriver: true,
      }),
      Animated.spring(logoScale, {
        toValue: 1,
        friction: 7,
        tension: 45,
        useNativeDriver: true,
      }),
    ]).start();

    Animated.loop(
      Animated.sequence([
        Animated.timing(pulse, {
          toValue: 1.08,
          duration: 1100,
          easing: Easing.inOut(Easing.ease),
          useNativeDriver: true,
        }),
        Animated.timing(pulse, {
          toValue: 1,
          duration: 1100,
          easing: Easing.inOut(Easing.ease),
          useNativeDriver: true,
        }),
      ])
    ).start();

    Animated.loop(
      Animated.timing(glow, {
        toValue: 1,
        duration: 1800,
        easing: Easing.inOut(Easing.ease),
        useNativeDriver: true,
      })
    ).start();

    const listenerId = progress.addListener(({ value }) => {
      setPercentage(Math.floor(value * 100));
    });

    Animated.timing(progress, {
      toValue: 1,
      duration: 2500,
      easing: Easing.inOut(Easing.ease),
      useNativeDriver: false,
    }).start();

    const unsubscribe = onAuthStateChanged(auth, (user) => {
      setTimeout(() => {
        if (user && user.emailVerified) {
          navigation.replace('Inicio');
        } else {
          navigation.replace('Login');
        }
      }, 2800);
    });

    return () => {
      progress.removeListener(listenerId);
      unsubscribe();
    };
  }, [glow, logoOpacity, logoScale, navigation, progress, pulse]);

  const widthInterpolate = progress.interpolate({
    inputRange: [0, 1],
    outputRange: ['0%', '100%'],
  });

  const shineTranslate = progress.interpolate({
    inputRange: [0, 1],
    outputRange: [-70, 290],
  });

  const glowOpacity = glow.interpolate({
    inputRange: [0, 0.5, 1],
    outputRange: [0.2, 0.55, 0.2],
  });

  return (
    <LinearGradient
      colors={['#0d121a', '#17152b', '#211833']}
      start={{ x: 0, y: 0 }}
      end={{ x: 1, y: 1 }}
      style={styles.container}
    >
      <View style={styles.lightBandTop} />
      <View style={styles.lightBandBottom} />

      <Animated.View style={[styles.logoGlow, { opacity: glowOpacity, transform: [{ scale: pulse }] }]} />

      <Animated.View
        style={[
          styles.logoCard,
          {
            opacity: logoOpacity,
            transform: [{ scale: logoScale }],
          },
        ]}
      >
        <Image
          source={require('../assets/logo.png')}
          style={styles.logo}
          resizeMode="contain"
        />
      </Animated.View>

      <Text style={styles.appName}>Louvor Soma</Text>
      <Text style={styles.caption}>Preparando sua experiência</Text>

      <View style={styles.progressWrap}>
        <View style={styles.progressHeader}>
          <Text style={styles.loadingText}>Iniciando</Text>
          <Text style={styles.percentText}>{percentage}%</Text>
        </View>

        <View style={styles.progressBarContainer}>
          <Animated.View style={[styles.progressBar, { width: widthInterpolate }]}>
            <LinearGradient
              colors={['#3cebff', '#436de9', '#0400ff']}
              start={{ x: 0, y: 0 }}
              end={{ x: 1, y: 0 }}
              style={styles.barGradient}
            />
            <Animated.View
              style={[
                styles.shineEffect,
                { transform: [{ translateX: shineTranslate }] },
              ]}
            />
          </Animated.View>
        </View>
      </View>
    </LinearGradient>
  );
}

